// lb_balance.cpp - apply a bundled balance patch to the in-RAM blueprints.
//
// Part of legobattles-decomp. Not an upstream ndsrecomp file; see
// port/runner/README.md.
//
// The three community balance mods change BP/Entities.ebp and nothing else
// (docs/101), so a balance patch is a list of changed bytes. Those lists are
// generated by tools/lb_genbalance.py and compiled in; the mods' authors are
// credited in lb_balance_data.h and docs/101.
//
// WHY DELTAS AND NOT THE WHOLE FILE
//
// The first version of this loaded a mod's Entities.ebp, decompressed it, and
// wrote its bytes over the in-RAM block. That worked mechanically and was
// WRONG. Comparing the decompressed file against RAM showed 35,598 differing
// bytes where the bundled vanilla-to-mod diff is only 835: the loader fixes up
// far more than the two string fields at +0x00 and +0x24, and writing the file
// wholesale would have clobbered every one of those fixups.
//
// Applying only the vanilla-to-mod DELTA touches 835 bytes that are genuinely
// balance values and leaves every loader-owned byte exactly as the game left
// it. Same result, none of the collateral.

#include "lb_overlay.h"
#include "lb_balance_data.h"

#include <cstdio>
#include <cstdint>
#include <vector>

extern "C" {
#include "runtime_arm.h"
}

namespace {

constexpr int kTableCount =
    (int)(sizeof(lb_balance_tables) / sizeof(lb_balance_tables[0]));

int g_applied_slot = 0;    // 0 vanilla, else the dropdown index

// docs/386: TAKING A PACK BACK OUT. The deltas hold only the pack's bytes, so
// there was no undo, and a change needed a restart. Now every byte any pack
// touches is kept as the game loaded it, in the runs' own order, before any
// pack is applied (lb_balance_snapshot, at the blueprints' discovery), and
// lb_balance_revert writes the applied pack's bytes back from it.
std::vector<std::vector<uint8_t>> g_vanilla;
unsigned int g_snap_base = 0u;

}  // namespace

// docs/386: one past the furthest byte any pack touches, from the block's
// base -- how much of the block has to hold still before it is used.
extern "C" unsigned int lb_balance_extent(void) {
    unsigned int end = 0u;
    for (int t = 0; t < kTableCount; ++t) {
        const LbBalanceTable& table = lb_balance_tables[t];
        for (uint32_t i = 0; i < table.run_count; ++i) {
            const unsigned int e = table.runs[i].offset + table.runs[i].length;
            if (e > end) end = e;
        }
    }
    return end;
}

extern "C" void lb_balance_snapshot(unsigned int blueprint_base) {
    g_vanilla.assign((size_t)kTableCount, std::vector<uint8_t>());
    for (int t = 0; t < kTableCount; ++t) {
        const LbBalanceTable& table = lb_balance_tables[t];
        std::vector<uint8_t>& v = g_vanilla[(size_t)t];
        v.reserve(table.byte_count);
        for (uint32_t i = 0; i < table.run_count; ++i) {
            const LbBalanceRun& run = table.runs[i];
            for (uint32_t j = 0; j < run.length; ++j)
                v.push_back(bus_read_u8(blueprint_base + run.offset + j));
        }
    }
    g_snap_base = blueprint_base;
}

// 1 when no pack is left applied; 0 when this one cannot be taken out (no
// snapshot of this block).
extern "C" int lb_balance_revert(unsigned int blueprint_base) {
    const int slot = g_applied_slot;
    if (slot <= 0) return 1;
    if (blueprint_base != g_snap_base || slot > (int)g_vanilla.size()) return 0;
    const LbBalanceTable& table = lb_balance_tables[slot - 1];
    const std::vector<uint8_t>& v = g_vanilla[(size_t)(slot - 1)];
    uint32_t k = 0, written = 0;
    for (uint32_t i = 0; i < table.run_count; ++i) {
        const LbBalanceRun& run = table.runs[i];
        for (uint32_t j = 0; j < run.length; ++j, ++k) {
            if (k >= v.size()) return 0;
            const uint32_t addr = blueprint_base + run.offset + j;
            if (bus_read_u8(addr) != v[k]) {
                bus_write_u8(addr, v[k]);
                ++written;
            }
        }
    }
    g_applied_slot = 0;
    std::fprintf(stderr, "[lb_balance] %s taken out: %u bytes back to the "
                 "loaded values\n", table.name, written);
    return 1;
}

// slot: 1 Rebalance, 2 FactionWars, 3 Funlite. Slot 0 is vanilla and does
// nothing; lb_balance_revert takes a pack back out (docs/386).
extern "C" int lb_balance_apply(int slot, unsigned int blueprint_base,
                                char* error, int error_size) {
    auto fail = [&](const char* why) {
        if (error && error_size > 0) std::snprintf(error, (size_t)error_size, "%s", why);
        return 0;
    };
    if (slot <= 0 || slot > kTableCount) return fail("no such balance patch");
    if (blueprint_base == 0u) return fail("blueprints not in RAM yet");

    const LbBalanceTable& table = lb_balance_tables[slot - 1];
    uint32_t written = 0;
    for (uint32_t i = 0; i < table.run_count; ++i) {
        const LbBalanceRun& run = table.runs[i];
        for (uint32_t j = 0; j < run.length; ++j) {
            const uint32_t addr = blueprint_base + run.offset + j;
            if (bus_read_u8(addr) != run.bytes[j]) {
                bus_write_u8(addr, run.bytes[j]);
                ++written;
            }
        }
    }

    g_applied_slot = slot;
    // "%u of %u bytes written" READ AS A FAILURE and it was not one. The loop
    // above writes only where the current byte DIFFERS, so this counter is the
    // number of bytes CHANGED -- the remainder are bytes the pack and vanilla
    // already agree on, which need no write. Reporting both numbers so nobody
    // else reads a shortfall into it; a genuine failure would show as a byte
    // that differs and stays differing, which is a different check entirely.
    std::fprintf(stderr,
                 "[lb_balance] %s applied: %u runs, %u of %u bytes changed "
                 "(%u already matched vanilla)\n",
                 table.name, table.run_count, written, table.byte_count,
                 table.byte_count - written);
    return 1;
}

extern "C" int lb_balance_is_applied(void) { return g_applied_slot != 0 ? 1 : 0; }
extern "C" int lb_balance_applied_slot(void) { return g_applied_slot; }

extern "C" const char* lb_balance_name(int slot) {
    if (slot <= 0 || slot > kTableCount) return "Off (Vanilla)";
    return lb_balance_tables[slot - 1].name;
}

extern "C" int lb_balance_byte_count(int slot) {
    if (slot <= 0 || slot > kTableCount) return 0;
    return (int)lb_balance_tables[slot - 1].byte_count;
}
